# Plan A: agent_value and agent_forecast (replace the TBD entry agent_value)
TBD_DONE = ["agent_value"]

add("agent_value", I_, GA, "ledger", "One row per dollar event an agent can claim: dollars detected, worked, submitted, accepted, recovered or avoided on one entity.",
    NOTE_ + " Append-only value ledger. A later stage is a new row, never an edit. Proof of money is a transactions row (an 835 payment).",
    "Dollars detected, worked, recovered and avoided by agent, payer, provider, specialty and CPT; recovery rate (recovered / detected); incremental value against the control group; value per agent run cost; overturn and recovery $ for appeals and underpayments",
    "1 the agent logs each stage and a later transactions row confirms it (transaction_id set), 2 claim paid after the action, row flagged is_estimate, 3 detected only, reported as unconfirmed",
    common("agent_value") + [
        L("agent_code", "VARCHAR(5)", M_, "", "Which agent gets the credit, A1 to A15.", "Always set by us"),
        L("value_stage", "VARCHAR(10)", M_, "", "Detected, worked, submitted, accepted, recovered, avoided. Lets one finding be followed from found to paid.", "Detected"),
        L("amount", "DECIMAL(12,2)", M_, "", "Dollars at this stage. Never negative; a payer takeback is a new row with value_kind = reversal.", "Amount at risk on the finding"),
        L("value_date", "DATE", M_, "", "Date of the event: detection date for detected, payment date for recovered.", "Run date"),
        L("entity_type", "VARCHAR(20)", M_, "", "Table the dollars belong to (claim, denial, claim_details and so on).", "Claim"),
        L("entity_id", "BIGINT", M_, "", "Internal ID in that table.", "Always set by us"),
        L("agent_finding_id", "BIGINT", I_, "agent_finding", "The finding behind it. Follow the chain from detected to recovered.", "Blank"),
        L("agent_decision_id", "BIGINT", I_, "agent_decision", "The decision that produced it.", "Blank"),
        L("practice_id", "INT", I_, "practice", "Reports by practice.", "From the entity"),
        L("claim_id", "BIGINT", I_, "claim", "The claim concerned.", "From the entity"),
        L("denial_id", "BIGINT", I_, "denial", "The denial concerned (appeal and overturn value).", "Blank"),
        L("payer_id", "INT", I_, "payer", "Value by payer, and the payer slice of a leak.", "From the claim"),
        L("provider_id", "INT", I_, "provider", "Value by rendering provider.", "From the claim"),
        L("specialty_id", "INT", I_, "specialty", "Value by specialty.", "From the provider"),
        L("cpt_code_id", "INT", I_, "cpt_code", "Value by procedure; blank for a payer total.", "Blank"),
        L("transaction_id", "BIGINT", I_, "transactions", "Proof: the 835 payment row that confirms recovered dollars. One payment is counted once.", "Blank: row is then an estimate"),
        L("is_holdout", "BIT", I_, "", "1 for a control group claim held back for measurement; the base of incremental value.", "0"),
        L("incremental_amount", "DECIMAL(12,2)", I_, "", "Dollars above what would have happened anyway, measured against holdout rows.", "Blank (not measured)"),
        L("value_kind", "VARCHAR(30)", O_, "", "Short type: underpayment, denial_overturn, rejection_fix, missed_charge, avoided_denial and so on.", "From the finding type"),
        L("is_estimate", "BIT", O_, "", "1 when no payment proves the amount (ladder step 2 or 3).", "1 when transaction_id is blank"),
        L("attribution_share", "DECIMAL(5,4)", O_, "", "Share of the dollars credited to this agent when several agents helped; 0 to 1.", "1")] + audit("agent_value", False))

add("agent_forecast", I_, GA, "snapshot", "One row per stored prediction: a cash, recoverable or claim payment forecast, with its range and, later, what actually happened.",
    NOTE_ + " Predictions are kept as made so accuracy is scored against what was said then. Filling in the actual is a new version; the earlier row stays.",
    "Forecast versus actual cash, WAPE, share of actuals inside the 80% range, claim payment chance calibration, recoverable forecast versus recovered, forecast by payer and week",
    "1 written by the forecasting agent at run time, actual filled from 835 payments in transactions, 2 forecast rebuilt from claim history (range lost, flagged is_reconstructed), 3 none: no backtest possible",
    common("agent_forecast") + [
        L("forecast_type", "VARCHAR(20)", M_, "", "Cash_week, cash_28d, cash_later, claim_week_chance, recoverable_month.", "Cash_week"),
        L("as_of_date", "DATE", M_, "", "Date the forecast was made. Each day's forecast is kept, so later scoring uses what was known then.", "Run date"),
        L("target_start_date", "DATE", M_, "", "First day of the period predicted.", "As-of date"),
        L("target_end_date", "DATE", M_, "", "Last day of the period predicted. For cash_later, as-of date plus 365 days.", "Start plus 6 days"),
        L("expected_amount", "DECIMAL(12,2)", M_, "", "Expected dollars in the period (chance times balance for one claim).", "From the model"),
        L("low_amount", "DECIMAL(12,2)", I_, "", "Low end of the range (80% by default).", "Blank (no range)"),
        L("high_amount", "DECIMAL(12,2)", I_, "", "High end of the range.", "Blank (no range)"),
        L("probability", "DECIMAL(5,4)", I_, "", "Chance a claim is paid in the period, 0 to 1. Blank for dollar-only rows.", "Blank"),
        L("claim_count", "INT", I_, "", "Open claims behind the row.", "Counted"),
        L("practice_id", "INT", I_, "practice", "Reports by practice.", "Client default"),
        L("payer_id", "INT", I_, "payer", "Forecast by payer; blank for all payers.", "Blank"),
        L("entity_type", "VARCHAR(20)", I_, "", "Claim for a claim chance; practice or payer for a total.", "Practice"),
        L("entity_id", "BIGINT", I_, "", "Internal ID of the claim for a claim chance; blank for totals.", "Blank"),
        L("actual_amount", "DECIMAL(12,2)", I_, "", "What was really paid in the period (835 payments in transactions). Filled when the period closes.", "Blank until known"),
        L("actual_known_date", "DATE", I_, "", "Date the actual was filled in.", "Blank until known"),
        L("within_range", "BIT", I_, "", "1 when the actual landed inside low and high; coverage is the share of 1s.", "Blank until known"),
        L("interval_level", "DECIMAL(3,2)", O_, "", "Confidence level of the range, 0.80 by default.", "0.80"),
        L("model_name", "VARCHAR(40)", O_, "", "Model or method used.", "Blank"),
        L("code_version", "VARCHAR(30)", O_, "", "Agent version, for replay.", "Blank")] + audit("agent_forecast"))

